from pathlib import Path
from html import escape
import json
import sys
sys.dont_write_bytecode = True
from home import render as render_home
ROOT=Path(__file__).resolve().parents[1]
CHECK='--check' in sys.argv
GENERATED={}
def write(path, content):
    relative=path.relative_to(ROOT).as_posix()
    assert relative in {'index.html','demo.html','beta.html','principles.html','status.html','about.html','privacy-policy.html','terms.html','thanks.html','404.html','sitemap.xml','robots.txt'} or (relative.split('/')[0] in {'en','zh'} and relative.count('/')==1 and relative.endswith('.html'))
    GENERATED[relative]=content
    if not CHECK:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(content,encoding='utf-8')
BASE='https://inputarchive.com'
EMAIL='haohongfei2001@gmail.com'

def build(lang):
    en=lang=='en'
    prefix='/' if en else '/zh/'
    def t(zh,eng): return eng if en else zh
    def link(page='index.html',anchor=''):
        return prefix + ('' if page=='index.html' else page) + anchor
    def a(page,label,cls='',anchor=''):
        return f'<a class="{cls}" href="{link(page,anchor)}">{label}</a>'
    def button(page,label,cls='button',anchor=''):
        return a(page,label+' <span aria-hidden="true">→</span>',cls,anchor)
    def head(page,title,desc,noindex=False):
        url=BASE+link(page)
        zhurl=BASE+'/zh/'+('' if page=='index.html' else page)
        enurl=BASE+'/'+('' if page=='index.html' else page)
        return f'''<!doctype html>
<html lang="{'en' if en else 'zh-CN'}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)}</title>
<meta name="description" content="{escape(desc,quote=True)}">
<meta name="theme-color" content="#fdfdfc">
<meta name="referrer" content="strict-origin-when-cross-origin">
{'<meta name="robots" content="noindex,follow">' if noindex else ''}
<link rel="canonical" href="{url}">
<link rel="alternate" hreflang="zh-Hans" href="{zhurl}">
<link rel="alternate" hreflang="en" href="{enurl}">
<link rel="alternate" hreflang="x-default" href="{enurl}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="PAIA">
<meta property="og:locale" content="{'en_US' if en else 'zh_CN'}">
<meta property="og:title" content="{escape(title,quote=True)}">
<meta property="og:description" content="{escape(desc,quote=True)}">
<meta property="og:url" content="{url}">
<meta property="og:image" content="{BASE}/assets/website/og-{lang}.png">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="{t('PAIA：说过的，成为下一步的起点。','PAIA: Turn what you’ve said into what’s next.')}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="{escape(title,quote=True)}">
<meta name="twitter:description" content="{escape(desc,quote=True)}">
<meta name="twitter:image" content="{BASE}/assets/website/og-{lang}.png">
<link rel="icon" href="/assets/website/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="/assets/website/site.css?v=3">
<script src="/assets/website/site.js?v=3" defer></script>
</head>
<body data-page="{page}" data-language="{lang}">
<a class="skip-link" href="#main">{t('跳到正文','Skip to content')}</a>'''
    def header(page):
        other=('/zh/'+('' if page=='index.html' else page)) if en else ('/'+('' if page=='index.html' else page))
        nav=a('index.html',t('首页','Home'))+a('index.html',t('如何使用','How it works'),anchor='#how')+a('principles.html',t('你的数据','Your data'))+a('about.html',t('为什么做 PAIA','Our story'))
        nav=nav.replace(f'href="{link(page)}"', f'href="{link(page)}" aria-current="page"')
        return f'''<header class="site-header"><div class="header-inner">
<div class="brand-lockup"><a class="wordmark" href="{prefix}" aria-label="{t('PAIA 首页','PAIA home')}">PAIA</a><span class="brand-tagline">{t('你的表达，<br>下一步的起点。','Your AI context,<br>for what’s next.')}</span></div>
<nav class="desktop-nav" aria-label="{t('主导航','Main navigation')}">{nav}</nav>
<div class="header-actions"><a class="language" href="{other}" lang="{'zh-CN' if en else 'en'}" hreflang="{'zh-Hans' if en else 'en'}">{t('EN','中文')}</a>{button('beta.html',t('申请内测','Get early access'),'button button-small')}</div>
<details class="mobile-menu"><summary aria-label="{t('打开导航菜单','Open navigation menu')}"><span aria-hidden="true">☰</span></summary><nav aria-label="{t('移动端导航','Mobile navigation')}">{nav}{a('demo.html',t('体验示例','Explore an example'))}{a('status.html',t('当前状态','Current status'))}</nav></details>
</div></header>'''
    def footer():
        return f'''<footer class="site-footer wrap"><div class="footer-top"><a class="wordmark" href="{prefix}">PAIA</a><p>{t('个人 AI 信息与上下文系统。','Your personal AI information & context system.')}</p></div><div class="footer-bottom"><nav aria-label="{t('页脚导航','Footer navigation')}">{a('about.html',t('为什么做 PAIA','Why PAIA'))}{a('status.html',t('当前状态','Status'))}{a('privacy-policy.html',t('隐私政策','Privacy'))}{a('terms.html',t('使用条款','Terms'))}<a href="mailto:{EMAIL}">{t('联系','Contact')}</a></nav><span>© 2026 PAIA · Private Beta</span></div></footer>'''
    def shell(page,title,desc,body,noindex=False,extra=''):
        out=head(page,title,desc,noindex)+header(page)+f'<main id="main" tabindex="-1">{body}</main>'+footer()+extra+'\n</body>\n</html>\n'
        dest=ROOT/('' if en else 'zh')/page
        dest.parent.mkdir(parents=True,exist_ok=True)
        write(dest,out)
        # Existing English deep links remain usable; canonical points to the root.
        if en: write(ROOT/'en'/page,out)
    def invitation():
        return f'''<section class="invitation wrap"><div><p class="eyebrow">PAIA / PRIVATE BETA</p><h2>{t('下一次对话，<br>带上你的积累。','For whatever<br><em>you think of next.</em>')}</h2><p>{t('从你已经在说的话开始，不必再经营一个知识库。','Start with the words you already write.<br>Not another knowledge base to maintain.')}</p></div><div class="invitation-action">{button('beta.html',t('申请内测','Get early access'))}<p class="small">{t('桌面 Chrome · ChatGPT 网页版 · 邀请制测试','Desktop Chrome · ChatGPT Web · Invite-only beta')}</p>{a('demo.html',t('先用示例试一遍','Explore an example'),'text-link')}</div></section>'''
    def statusmini():
        return f'''<div class="availability"><span class="status-dot" aria-hidden="true"></span><span>{t('桌面 Chrome 扩展 · ChatGPT 网页版 · 邀请制测试','Desktop Chrome extension · ChatGPT Web · Invite-only beta')}</span></div>'''
    home=render_home(t,a,button,statusmini)
    shell('index.html',t('PAIA — 对话结束，思考继续','PAIA — Personal context for what’s next'),t('让你在 AI 对话中已经产生的表达、判断和问题继续属于你：可以找回、修改、理解，并由你决定哪些成为下一次 AI 的上下文。','Keep the expressions, decisions and questions you already create with AI. Revisit, revise and understand them—then decide what becomes context for what comes next.'),home)

    # Every record is fictional; no private-source prose or user archive material.
    records=[('a','2026-08-12',t('产品方向','Product direction'),t('我在做一款给独立创作者的工具。第一版只解决素材找回，不做内容生成。','I’m building a tool for independent creators. The first version should help recover existing material, not generate content.')),
             ('b','2026-09-03',t('目标用户','Intended users'),t('目标用户已经有持续的创作项目。他们需要接上已有的积累，而不是更多从零开始的建议。','The users already have ongoing creative projects. They need to build on what they have, not get more advice that starts from zero.')),
             ('c','2026-09-15',t('实现边界','Scope boundary'),t('先验证用户是否能更快找回素材。暂不做多人协作。','First test whether users can recover material faster. Leave collaboration out for now.'))]
    recordhtml=''.join(f'''<article class="sample-record" data-record="{id}"><div class="record-meta"><span>{date}</span><span>{escape(title)}</span></div><label for="edit-{id}">{t('现在要用的文字','Working text')}</label><textarea id="edit-{id}" class="working-text" rows="3" spellcheck="false">{escape(text)}</textarea><details class="source-details"><summary>{t('核对原始记录','Check the original record')}</summary><blockquote class="source-text">{escape(text)}</blockquote><p>{t('这是此示例的固定原始记录，编辑上方文字不会改变它。','This is the fixed original in this sample. Editing the working text above does not change it.')}</p></details></article>''' for id,date,title,text in records)
    choices=''.join(f'''<label class="material-choice"><input type="checkbox" data-select="{id}" {'checked' if id!='c' else ''}><span><strong>{escape(title)}</strong><small>{date}</small></span></label>''' for id,date,title,text in records)
    demo=f'''<section class="page-intro wrap"><p class="eyebrow">{t('CONTEXT DEMO / 从材料到下一次任务','CONTEXT DEMO / FROM MATERIAL TO THE NEXT TASK')}</p><h1>{t('为你的下一次 AI，<br>准备好上下文。','Your next AI task.<br>Your context, ready.')}</h1><p class="lead">{t('你正在评估一款创作工具的第一版。找回先前确定的方向，更新材料，再为 AI 准备一份范围明确的上下文。','You’re reviewing the first version of a creator tool. Recover its direction, revise the material, and prepare a clear context for AI.')}</p><div class="demo-disclosure"><strong>{t('交互示意，不是正在运行的扩展','An interactive illustration, not the running extension')}</strong><p>{t('全部为虚构数据。不连接你的 ChatGPT 或 PAIA，不调用 AI，不上传或持久保存本页输入。刷新会清除修改；请不要输入私人资料。','All data is fictional. This page does not connect to ChatGPT or PAIA, call AI, upload your input, or persist it. Reloading clears edits. Please do not enter private information.')}</p></div></section>
<section class="demo wrap" data-demo data-language="{lang}"><noscript><p class="notice">{t('开启 JavaScript 后可体验编辑、选择和复制。下面的示例说明可直接阅读，申请表也不依赖 JavaScript。','Enable JavaScript to try editing, selection and copying. You can still read this explanation and use the beta form without JavaScript.')}</p></noscript><div class="demo-tabs" role="tablist" aria-label="{t('体验步骤','Demo steps')}">{''.join(f'<button role="tab" id="tab-{i}" aria-controls="panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-step="{i}"><span>0{i+1}</span>{name}</button>' for i,name in enumerate([t('留下','Capture'),t('找回与修改','Revisit'),t('理解','Understand'),t('复用','Reuse')]))}</div>
<section id="panel-0" class="demo-panel" role="tabpanel" aria-labelledby="tab-0"><div class="demo-panel-heading"><p class="eyebrow">01 / CAPTURE</p><h2>{t('先有自己的记录。','First, a record of your own.')}</h2><p>{t('正式扩展在你明确同意后保存支持页面上的用户文字。这个例子已经准备好三条输入，来自同一个项目里的不同会话。','The extension saves eligible user text on supported pages after your consent. This sample already contains three inputs from separate conversations in one project.')}</p></div><div class="capture-sample"><span class="label">{t('示例项目','SAMPLE PROJECT')}</span><h3>{t('创作工具','Creator tool')}</h3>{''.join(f'<p><time datetime="{d}">{d}</time><span>{escape(title)}</span></p>' for _,d,title,_ in records)}</div><p class="small">{t('这个页面没有执行采集。打开旧对话的补录，也不等于导入整个账户的历史。','No capture happens on this page. Supplementing an opened conversation is not the same as importing your entire account history.')}</p><button class="button" data-next disabled>{t('找回产品方向','Find the product direction')} <span aria-hidden="true">→</span></button></section>
<section id="panel-1" class="demo-panel" role="tabpanel" aria-labelledby="tab-1" hidden><div class="demo-panel-heading"><p class="eyebrow">02 / REVISIT</p><h2>{t('找回来，也可以继续修改。','Find it. Then work with it.')}</h2><p>{t('搜“用户”试试，再直接改一句工作文字。展开原始记录，看看有什么没有改变。','Try searching for “users”, then edit a working sentence. Open the original record to see what stays unchanged.')}</p></div><label class="search-label" for="sample-search">{t('在这三条示例输入中查找','Search these three sample inputs')}</label><input type="search" id="sample-search" placeholder="{t('试试：用户','Try: users')}" autocomplete="off"><p id="search-status" class="small" role="status"></p><div class="sample-records">{recordhtml}</div><p class="empty-search" hidden>{t('没有匹配。试试另一个关键词，或清空搜索。','No match. Try another keyword or clear the search.')}</p><button class="button" data-next>{t('放在一个主题里看','See the topic')} <span aria-hidden="true">→</span></button></section>
<section id="panel-2" class="demo-panel" role="tabpanel" aria-labelledby="tab-2" hidden><div class="demo-panel-heading"><p class="eyebrow">03 / UNDERSTAND</p><h2>{t('同一个主题，不同时间的表达。','One topic. Expressions over time.')}</h2><p>{t('会话告诉你在哪里说过；主题帮助你把相关内容放在一起看。下方会跟随此示例中的工作文字，不额外推断你的立场。','Conversations tell you where you said something. A topic brings related expressions together. This sample uses the working text you just edited, without inferring new beliefs.')}</p></div><div class="topic-sample"><div class="topic-heading"><h3>{t('创作工具：第一版的产品范围','Creator tool: the first release scope.')}</h3><span class="small">{t('固定示例主题','Fixed sample topic')}</span></div><div data-topic-records></div></div><p class="small">{t('这里不运行自动分类或 AI 整理。正式产品中的可选 AI 整理属于另外授权的处理，不能把输出当成未经核对的个人事实。','This page does not run automatic classification or AI organization. Optional AI organization in the product is separately authorized processing, not an unchecked source of personal facts.')}</p><button class="button" data-next>{t('为这次任务选材料','Choose material for this task')} <span aria-hidden="true">→</span></button></section>
<section id="panel-3" class="demo-panel" role="tabpanel" aria-labelledby="tab-3" hidden><div class="demo-panel-heading"><p class="eyebrow">04 / REUSE</p><h2>{t('只带上这次需要的。','Take only what this task needs.')}</h2><p>{t('选择、预览，再复制或导出。更改任务、选择或工作文字后，需要重新准备预览，不会默默输出旧版本。','Select, review, then copy or export. Changing the task, selection or working text requires a fresh preview, rather than silently releasing an older version.')}</p></div><div class="context-layout"><div><label for="sample-task">{t('这次要做什么？','What are you doing this time?')}</label><textarea id="sample-task" rows="3">{t('评估第一版的产品范围，指出应该保留和暂缓的部分。','Review the scope of the first version. What should stay, and what should wait?')}</textarea><fieldset><legend>{t('你明确选择的材料','Material you explicitly choose')}</legend>{choices}</fieldset><button class="button" data-build>{t('准备本地预览','Prepare local preview')}</button></div><div class="context-output"><label for="context-preview">{t('将要复制或导出的完整文字','The exact text to copy or export')}</label><textarea id="context-preview" rows="12" readonly placeholder="{t('还没有准备上下文，也没有发送任何内容。','No context prepared. Nothing has been sent.')}"></textarea><p class="context-status small" role="status">{t('未发送给任何 AI','Not sent to any AI')}</p><div class="actions"><button class="button" data-copy disabled>{t('复制文字','Copy text')}</button><button class="button button-outline" data-export disabled>{t('导出 Markdown','Export Markdown')}</button></div><p class="small">{t('复制和导出只在你点击后发生。PAIA 无法收回你之后交给外部系统的副本。','Copy and export happen only when you click. PAIA cannot recall a copy you later give to another system.')}</p></div></div></section><div class="demo-bottom"><button class="text-button" data-reset disabled>{t('重置示例，清除本页修改','Reset sample and clear edits')}</button><span class="small" data-demo-status role="status"></span>{a('beta.html',t('这对我有用，申请内测','This is useful — request beta access'),'text-link')}</div></section>'''
    shell('demo.html',t('用一个示例体验 PAIA — 找回、修改、复用','Try PAIA with a sample — Find, edit, reuse'),t('用虚构项目走完 PAIA 的找回与复用。无需安装，不连接私人档案，不调用 AI。','Explore PAIA with a fictional project. No installation, private archive access or AI calls.'),demo,True,'<script src="/assets/website/demo.js?v=1" defer></script>')

    beta=f'''<section class="page-intro wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h1>{t('参与下一代<br>个人 AI 体验。','Help shape a more<br>personal AI experience.')}</h1><p class="lead">{t('适合已经经常用 ChatGPT 思考、研究或创作，也确实遇到过“以前说过，却难以继续使用”的人。','For people who regularly think, research or create with ChatGPT—and have struggled to put past expressions to use again.')}</p>{statusmini()}</section><section class="beta-layout wrap"><div><form class="beta-form" action="https://formsubmit.co/haohongfei2001@gmail.com" method="POST"><input type="hidden" name="_subject" value="PAIA Private Beta application"><input type="hidden" name="_template" value="table"><input type="hidden" name="_captcha" value="false"><input type="hidden" name="_next" value="{BASE}{link('thanks.html')}"><input type="hidden" name="language" value="{lang}"><div class="honeypot" aria-hidden="true"><label for="website-url">Leave this field empty</label><input id="website-url" type="text" name="_honey" tabindex="-1" autocomplete="off"></div><h2>{t('申请加入测试','Request an invitation')}</h2><label for="beta-email">{t('邮箱','Email')} <span class="required">{t('必填','Required')}</span></label><input id="beta-email" name="email" type="email" autocomplete="email" required maxlength="254" aria-describedby="email-hint"><p class="field-hint" id="email-hint">{t('用于 Beta 联系和邀请，不要求填写真实姓名。','For beta contact and invitations. No real name required.')}</p><label for="beta-frequency">{t('你使用 ChatGPT 的频率','How often do you use ChatGPT?')}</label><select id="beta-frequency" name="frequency"><option value="">{t('选填','Optional')}</option><option value="daily">{t('每天','Daily')}</option><option value="several-times-week">{t('每周数次','Several times a week')}</option><option value="weekly-or-less">{t('每周或更少','Weekly or less')}</option></select><label for="beta-goal">{t('你最想找回或复用什么？','What would you like to recover or reuse?')}</label><textarea id="beta-goal" name="goal" rows="4" maxlength="1000" placeholder="{t('选填。描述一个场景即可，不要粘贴聊天记录或私人资料。','Optional. Describe a situation, not private information or actual chat text.')}" aria-describedby="form-privacy"></textarea><label class="consent"><input type="checkbox" name="contact_consent" value="yes" required><span>{t('我同意将以上申请信息交给 FormSubmit 转发至项目邮箱，用于 Beta 招募与联系。','I agree to have FormSubmit forward this application to the project email for beta recruitment and contact.')}</span></label><p class="small" id="form-privacy">{t('只有提交此表单才会发送这些信息。不会发送你的 PAIA 档案。可随时通过项目邮箱申请删除；请勿填写敏感信息。','Only submitting this form sends this information. It does not send your PAIA archive. You can request deletion through the project email. Do not include sensitive information.')} {a('privacy-policy.html',t('隐私政策','Privacy policy'))}</p><button class="button" type="submit">{t('提交申请','Submit application')} <span aria-hidden="true">↗</span></button><p class="small">{t('提交后将前往 FormSubmit 处理。以该服务的提交结果为准；申请不代表已经获邀。','Submission is handled by FormSubmit. Its response determines delivery; applying does not mean you have been invited.')}</p></form><p class="small form-alternative">{t('表单无法使用？也可以直接写信：','Form unavailable? You can email instead:')} <a href="mailto:{EMAIL}?subject=PAIA%20Private%20Beta">{EMAIL}</a></p></div><aside class="beta-aside"><h2>{t('申请后会怎样','What happens next')}</h2><ol class="steps-list"><li><h3>{t('我们了解你的使用场景','We review your use case')}</h3><p>{t('招募以当前测试范围为准，不承诺固定回复时间或一定获得名额。','Invitations depend on the current testing scope. There is no guaranteed place or response time.')}</p></li><li><h3>{t('获邀后收到安装说明','Invited participants receive instructions')}</h3><p>{t('包括可用版本、安装方式、当前限制和反馈方式。不是立即安装，也不是公开商店发布。','Including the available build, setup, limitations and feedback path. This is not an instant installation or public store release.')}</p></li><li><h3>{t('从非关键材料开始','Start with non-critical material')}</h3><p>{t('先验证保存、找回和复用是否适合你。重要资料始终保留独立备份。','Check whether capture, retrieval and reuse help you. Always keep independent backups of important data.')}</p></li></ol><div class="aside-note"><strong>{t('还不确定？','Still exploring?')}</strong><p>{t('先用示例体验，不需要提供邮箱。','Try the sample first. No email needed.')}</p>{a('demo.html',t('打开示例','Open the sample'),'text-link')}</div></aside></section>'''
    shell('beta.html',t('申请 PAIA Private Beta','Request PAIA Private Beta access'),t('申请参与 PAIA 邀请制测试。桌面 Chrome 扩展，围绕 ChatGPT 网页版；先查看范围、数据边界和申请流程。','Request an invitation to test PAIA for desktop Chrome and ChatGPT Web. Review the scope, data boundaries and application process.'),beta)

    trust=f'''<section class="page-intro wrap"><p class="eyebrow">{t('数据与信任','DATA & TRUST')}</p><h1>{t('长期留下，<br>不等于交出控制。','Keep it for the long term.<br>Keep control of it.')}</h1><p class="lead">{t('PAIA 首先是你自己的私人材料，不是默认交给模型消费的数据。下面说明当前设计与实现中的具体边界，而不是一份无限安全的承诺。','PAIA is your private material first, not a default data feed for a model. These are concrete boundaries in the current design and implementation, not a promise of absolute security.')}</p></section><section class="article-layout wrap"><nav class="article-nav" aria-label="{t('本页目录','On this page')}"><a href="#local">{t('本机与外部','Local and external')}</a><a href="#source">{t('原话与修改','Originals and edits')}</a><a href="#permission">{t('不同的授权','Separate permissions')}</a><a href="#exit">{t('备份与离开','Backup and exit')}</a></nav><div class="prose"><section id="local"><h2>{t('日常使用不必先把档案上传。','Everyday use does not require an archive upload.')}</h2><p>{t('核心档案默认保存在 Chrome 扩展的本地存储中。普通阅读、编辑、词面搜索以及上下文准备在本机完成。这个官网不连接你的扩展档案。','The core archive is stored locally in the Chrome extension. Ordinary reading, editing, lexical search and context preparation happen on-device. This website does not connect to your extension archive.')}</p><p>{t('“本地优先”不等于“任何情况下都不出设备”。主动使用可选外部 AI 整理时，当前版本可向配置的 DeepSeek API 发送获准处理的材料；手动复制、导出或在其他系统使用材料，也会产生外部副本。','“Local-first” does not mean “nothing can ever leave the device.” Explicit use of optional external AI organization can send authorized material to the configured DeepSeek API in the current build. Copying, exporting or using material in another system can also create external copies.')}</p><p>{t('本机保存不是加密声明，也不能抵御设备被入侵、浏览器资料被删除或所有存储故障。请保护设备，并保留独立备份。','Local storage is not an encryption claim. It cannot protect against every compromised device, deleted browser profile or storage failure. Protect your device and keep independent backups.')}</p></section><section id="source"><h2>{t('今天修改文字，不改写昨天发生的事。','Editing today does not rewrite yesterday.')}</h2><p>{t('Source 记录保存来源事实；工作文字用于日常阅读和修改；AI 整理是基于材料生成的呈现。普通编辑不覆盖 Source。用户手动修改和排除，不应该被自动处理悄悄覆盖。','Source records preserve what came from the source. Working text is for everyday reading and editing. AI organization is a presentation derived from that material. Ordinary edits do not overwrite Source. Automatic processing should not silently undo your edits or exclusions.')}</p><div class="source-comparison"><div><span class="label">{t('原始记录 · 示例','ORIGINAL RECORD · EXAMPLE')}</span><p>{t('每期只写一个真正想弄清楚的问题。','Each letter should explore one question I genuinely want to understand.')}</p></div><div><span class="label">{t('现在的工作文字 · 示例','CURRENT WORKING TEXT · EXAMPLE')}</span><p>{t('每期从一个具体观察出发，讨论一个真正想弄清楚的问题。','Begin each letter with a concrete observation, then explore one question I genuinely want to understand.')}</p></div></div><p>{t('发送过一段文字，也不自动意味着认同它。引用、第三方材料、假设和角色扮演，都不能无条件被归结为你的长期观点。AI 整理仍需要核对，不应编造一段顺滑的“思想成长史”。','Sending a passage does not necessarily mean believing it. Quotes, third-party material, hypotheses and role-play should not automatically become your lasting opinions. Review AI organization; it should not invent a tidy story of personal growth.')}</p></section><section id="permission"><h2>{t('四件事，四种边界。','Four actions. Separate boundaries.')}</h2><dl class="boundary-list"><div><dt>{t('保存输入','Keep inputs')}</dt><dd>{t('授权扩展保留符合条件的用户文字。不是许可任意读取其他页面、草稿或文件。','Consent to retain eligible user text. Not permission to read arbitrary pages, drafts or files.')}</dd></div><div><dt>{t('调用外部 AI','Use external AI')}</dt><dd>{t('另外明确触发，对获准范围进行处理。不是因为已经保存，就自动允许上传。','A separate, explicit action over authorized material. Retention is not permission to upload.')}</dd></div><div><dt>{t('复制或导出 Context','Copy or export context')}</dt><dd>{t('先选择并预览，再由你实际使用。不代表已经发给 AI，也不能收回外部副本。','Select and preview, then use it yourself. Preparing is not sending; external copies cannot be recalled.')}</dd></div><div><dt>{t('设备同步和连接访问','Device sync and connected access')}</dt><dd>{t('需要独立的产品与授权边界。通用云同步及真实外部 AI 读取连接器不是当前上线承诺。','Require independent product and permission boundaries. General cloud sync and a real external AI reader connector are not current release claims.')}</dd></div></dl><p>{t('隐藏、从主题移除、从档案移除、永久删除与“不能用于 AI”也不是同一个动作。过滤只是阅读可见性，不是删除，更不是授权。删除在 PAIA 可控制的范围内生效，不承诺删除第三方平台或你已导出的副本。','Hiding, removing from a topic, removing from the archive, permanent deletion and excluding from AI use are different actions. Filtering changes reading visibility, not deletion or permission. PAIA deletion applies within its control, not to third-party platforms or copies already exported.')}</p></section><section id="exit"><h2>{t('值得托付，也应该方便离开。','Worth keeping. Possible to leave.')}</h2><p>{t('开放导出用于带走可理解的材料，备份用于恢复整个库。当前代码已有相关路径，但真实大库、私人官方导出及消费级分发的部分验证仍未完成。Beta 不是唯一副本；更新或恢复之前，先确认独立备份。','Open export lets you take understandable material with you; backup is for library recovery. Those paths exist in the current code, but parts of real large-library, private official-export and consumer-distribution verification are still incomplete. Beta should not be your only copy. Check independent backups before updating or restoring.')}</p><p>{t('原平台删除聊天，不会自动删除 PAIA 已保存的内容。你在 PAIA 的删除，也不能自动删除原平台上的聊天。','Deleting a chat on the original platform does not automatically delete content already kept in PAIA. Deleting in PAIA does not automatically delete the original chat.')}</p><p>{a('status.html',t('当前能力与验证边界','Current capability and verification boundaries'),'text-link')}</p></section><section><h2>{t('这个网站本身呢？','What about this website?')}</h2><p>{t('没有分析脚本、广告跟踪器、远程字体或档案连接。示例输入只在本页内存中使用，刷新即清除。只有你主动提交 Beta 申请时，表单信息才会经 FormSubmit 发送到项目邮箱。网站托管与表单服务仍有各自的数据处理边界。','No analytics scripts, ad trackers, remote fonts or archive connection. Sample inputs live only in page memory and clear on reload. Only submitting a beta application sends its fields through FormSubmit to the project email. Website hosting and the form provider have their own data-processing boundaries.')}</p><p>{a('privacy-policy.html',t('阅读隐私政策','Read the privacy policy'),'text-link')}</p></section></div></section>{invitation()}'''
    shell('principles.html',t('PAIA — 数据与信任','PAIA — Data and trust'),t('了解 PAIA 的本地存储、来源保真、用户编辑、AI 授权、复制导出与备份边界。','Understand PAIA’s local storage, source fidelity, editing, AI permission, export and backup boundaries.'),trust)

    status=f'''<section class="page-intro wrap"><p class="eyebrow">{t('当前状态 · 核对于 2026-09-26','CURRENT STATUS · REVIEWED 26 SEP 2026')}</p><h1>{t('当前能力。<br>下一步进化。','What exists.<br>What is still ahead.')}</h1><p class="lead">{t('PAIA 正在 Private Beta 中迭代。已有实现不等于所有场景都通过真实环境认证，也不等于已经公开发布。','PAIA is evolving in private beta. An implemented capability is not the same as full real-world certification or a public release.')}</p>{statusmini()}</section><section class="status-page wrap"><article><span class="label">{t('01 / 当前代码已有','01 / IMPLEMENTED IN THE CURRENT BUILD')}</span><h2>{t('保存、找回，以及明确的再次使用。','Capture, revisit, and deliberate reuse.')}</h2><ul><li>{t('经同意采集支持的 ChatGPT 页面中符合条件、已显示的用户文字；可暂停。','Consent-based capture of eligible, displayed user text on supported ChatGPT pages; capture can be paused.')}</li><li>{t('按项目与会话导航、连续阅读、工作文字编辑及词面搜索。直接编辑、来源核对和检索改进已合入；思想库体验继续迭代。','Project and conversation navigation, continuous reading, working-text editing and lexical search. Editing and retrieval UX are still being refined.')}</li><li>{t('跨会话主题阅读，以及基于来源材料的可选 AI 整理。AI 输出需要核对。','Cross-conversation topic reading and optional AI organization grounded in source material. AI output needs review.')}</li><li>{t('从输入或主题明确选材料，准备并预览上下文，再复制或导出。材料变化后旧预览失效。','Explicit material selection from inputs or topics, context preparation and preview, then copy or export. Changed material invalidates an old preview.')}</li><li>{t('开放导出、分段备份与分阶段恢复的实现路径。请参照下方验证限制。','Implemented paths for open export, segmented backup and staged restore. See verification limits below.')}</li></ul></article><article><span class="label">{t('02 / 仍在验证','02 / VERIFICATION IN PROGRESS')}</span><h2>{t('工程测试，不代替真实使用。','Engineering tests are not real-world proof.')}</h2><p>{t('当前仍有真实 ChatGPT 环境、实体设备、签名分发与同身份更新，以及私人官方历史导出等外部证据缺口。大规模合成数据测试已经用于工程验证，但不能冒充你的真实资料已安全恢复。','Remaining external evidence includes live ChatGPT journeys, physical devices, signed distribution and same-identity updates, and private official history exports. Large synthetic datasets have been used in engineering tests; that is not proof that your real archive has been safely restored.')}</p><p>{t('因此，目前不承诺一键完整导入全部历史、所有来源兼容、无限容量、无损的十年保存保证或公开商店即装即用。','We do not currently promise one-click import of all history, universal source compatibility, unlimited capacity, a ten-year lossless-storage guarantee, or immediate public-store installation.')}</p></article><article><span class="label">{t('03 / 后续方向，尚非当前上线能力','03 / FUTURE DIRECTION, NOT CURRENT AVAILABILITY')}</span><h2>{t('让更多表达继续有用，<br>但不提前借未来作承诺。','More ways to keep thinking.<br>No borrowing from the future.')}</h2><p>{t('真正的外部 AI 读取连接器、更强语义检索、更多个人表达来源、手机上的快速记录与语音，以及独立授权的跨设备能力，属于后续产品方向。它们不应从官网示意图被误读为已经完整可用。','A real external AI reader connector, stronger semantic retrieval, more sources of personal expression, quick writing and voice on mobile, and separately authorized cross-device capabilities are future directions. Website illustrations should not imply that these are already fully available.')}</p></article><div class="status-footnote"><p>{t('本页依据仓库已合入的实现与 Consumer Product v1 状态核对，不把 open PR 当作已发布能力。技术状态会继续变化，获邀时以提供的版本与说明为准。','This page is checked against integrated repository code and Consumer Product v1 status, not open PRs treated as releases. Technical status will continue to evolve; invitations describe the actual build provided.')}</p><a href="https://github.com/haohongfei2001-png/paia" rel="noreferrer">{t('查看公开仓库','View the public repository')} ↗</a></div></section>{invitation()}'''
    shell('status.html',t('PAIA — 当前能力与后续方向','PAIA — Current capabilities and future direction'),t('PAIA Private Beta 的已实现能力、未完成验证和未来方向。明确区分工程实现与生产发布。','Implemented capabilities, incomplete verification and future directions for the PAIA private beta.'),status)

    about=f'''<section class="page-intro wrap"><p class="eyebrow">WHY PAIA</p><h1>{t('你在对话里投入的，<br>不应该只属于那次对话。','What you put into a chat<br>should outlast that chat.')}</h1></section><article class="prose about-prose wrap"><p class="lead">{t('我们越来越多地借助 AI 想事情。写下背景，解释选择，推翻假设，反复描述自己在意什么。久而久之，这些不只是输入，它们也是我们留给自己的材料。','More of our thinking now happens with AI. We explain the background, weigh a choice, question an assumption, and describe what matters. Over time, these are more than inputs. They are material we have made for ourselves.')}</p><p>{t('PAIA 从一个小问题开始：这些已经自然产生的表达，能不能更容易被自己找回、理解、修正，然后继续使用？不是要求人再经营一个知识库，也不是让 AI 默认知道一切。','PAIA began with a small question: could the expressions we already produce become easier to recover, understand, revise and reuse? Not by asking people to maintain another knowledge base. Not by giving AI access to everything.')}</p><h2>{t('由你掌握，为下一次 AI 所用。','Yours to control. Ready for your next AI task.')}</h2><p>{t('Input Archive 留住具体内容和来源。Thought Library 帮助跨会话看一个长期主题。AI Context 让你为这次任务选择要用的部分。它们共同服务一个过程：留下、回看、理解、复用。','Input Archive keeps concrete material and its source. Thought Library helps you see a lasting topic across chats. AI Context lets you choose what belongs in the next task. Together they serve one loop: capture, revisit, understand, reuse.')}</p><p>{t('这是一个持续设计与开发中的独立项目。真实价值要由长期使用来证明：有没有更容易找回，愿不愿意回来，能不能少重复一次，继续想深一点。功能数量和测试通过，不能代替这些答案。','This is an independently developed product in active iteration. Its value must be established through lasting use: easier retrieval, a reason to return, less repetition, and room to think further. Feature counts and passing tests cannot answer those questions.')}</p><p>{a('demo.html',t('从一个示例开始','Start with one example'),'text-link')}</p></article>{invitation()}'''
    shell('about.html',t('为什么做 PAIA','Why PAIA exists'),t('PAIA 为什么存在：让在 AI 对话中自然产生的表达，成为自己可找回、理解、修改和复用的私人材料。','Why PAIA exists: to make the expressions you naturally create in AI conversations recoverable, understandable, editable and reusable.'),about)

    privacy_sections=[
      (t('1. 核心原则','1. Core principles'),t('PAIA 当前以本地优先方式运行。核心档案数据默认保存在用户设备上，产品设计优先让保存、检索、备份和多数组织逻辑在本地完成。','PAIA currently operates local-first. Core archive data is stored on the user’s device by default. The product prioritizes local capture, retrieval, backup and most organization logic.')),
      (t('2. AI 相关数据使用','2. AI-related data use'),t('PAIA 不默认把完整档案交给外部 AI。需要调用外部 AI 的功能，应由用户明确触发，并尽量只处理完成当前任务所必要的内容。AI Context 的授权、排除和预览应当先由用户确认。','PAIA does not give external AI the complete archive by default. Features that call external AI should be explicitly triggered by the user and process only what is needed for the task. AI Context permissions, exclusions and previews should be confirmed by the user first.')),
      (t('3. 本网站','3. This website'),t('当前公开展示网站不连接用户的 PAIA 档案，也不设置分析脚本或行为跟踪器。网站仅用于说明产品理念、交互与当前开发状态。','This public website does not connect to a user’s PAIA archive or install analytics scripts or behavioral trackers. It explains the product, interactions and current development status.')),
      (t('4. Private Beta 申请','4. Private beta applications'),t('Private Beta 申请表通过第三方表单转发服务 FormSubmit 将你主动填写的信息发送到项目联系邮箱 haohongfei2001@gmail.com。申请信息仅用于当前 Beta 的招募、筛选与联系，并会在不再需要用于 Beta 招募后删除。你可以随时通过项目联系邮箱要求提前删除已提交的申请信息。请不要提交敏感信息。','The private beta form uses the third-party forwarding service FormSubmit to send the information you enter to haohongfei2001@gmail.com. Application information is used only for current beta recruitment, selection and contact, and is deleted when no longer needed for recruitment. You can request earlier deletion through the project email at any time. Do not submit sensitive information.')),
      (t('5. Private Beta','5. Private beta'),t('PAIA 仍处于 Private Beta。具体数据结构、同步方式和可选 AI 功能可能继续调整。若未来引入云同步、账户系统或新的外部服务，会在正式启用前更新本政策并说明相应数据边界。','PAIA remains in private beta. Data structures, synchronization approaches and optional AI features may change. If cloud sync, accounts or new external services are introduced, this policy will be updated and their data boundaries explained before activation.')),
      (t('6. 用户控制与删除','6. User control and deletion'),t('产品目标是让用户保留对自己档案的最终控制权，包括查看、编辑、导出和删除。具体能力以当前 Beta 版本实际提供的功能为准。','The product aims to keep users in control of their archives, including viewing, editing, exporting and deleting. Specific capabilities depend on what the current beta build actually provides.'))]
    terms_sections=[
      (t('1. Beta 状态','1. Beta status'),t('PAIA 当前处于 Private Beta。功能、数据结构、界面和支持范围可能持续变化，部分能力可能不稳定或暂时不可用。','PAIA is currently in private beta. Features, data structures, interfaces and support scope may change. Some capabilities may be unstable or temporarily unavailable.')),
      (t('2. 用户数据','2. User data'),t('用户对自己输入、编辑和导入的内容保留相应权利。PAIA 的产品目标是让这些内容保持可查看、可管理和可导出，而不是通过锁定用户数据建立使用门槛。','Users retain the relevant rights in content they enter, edit and import. PAIA aims to make this material viewable, manageable and exportable, rather than create barriers by locking in user data.')),
      (t('3. 备份责任','3. Backups'),t('在 Beta 阶段，用户不应把 PAIA 作为自己重要数据的唯一副本。对于需要长期保存的内容，请同时保留独立备份。','During beta, do not use PAIA as the only copy of important data. Keep independent backups of material that needs long-term preservation.')),
      (t('4. 合理使用','4. Acceptable use'),t('请勿利用 PAIA 进行违法活动、未经授权的数据收集、侵犯他人隐私或知识产权，或规避第三方平台的访问和使用限制。','Do not use PAIA for unlawful activity, unauthorized data collection, violations of others’ privacy or intellectual property, or circumvention of third-party access and usage restrictions.')),
      (t('5. 第三方服务','5. Third-party services'),t('PAIA 可能与浏览器、AI 服务或其他第三方平台配合使用。第三方服务的可用性、条款和技术变化不由 PAIA 控制，相关功能可能因此调整。','PAIA may work with browsers, AI services and other third-party platforms. PAIA does not control their availability, terms or technical changes, which may require changes to related features.')),
      (t('6. 可用性与责任边界','6. Availability and limitations'),t('Beta 版本按当前状态提供，不承诺持续、无错误或永久可用。产品会尽力降低数据风险，但用户仍应为重要资料保留独立备份。','The beta is provided in its current state, without a promise of continuous, error-free or permanent availability. The product seeks to reduce data risks, but users should keep independent backups of important material.'))]
    for page,title,sections,date in [('privacy-policy.html',t('隐私政策','Privacy policy'),privacy_sections,'2026-09-11'),('terms.html',t('使用条款','Terms'),terms_sections,'2026-09-10')]:
        content=f'''<section class="page-intro wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h1>{title}</h1><p class="small">{t('政策内容最后更新','Policy content last updated')}: {date} · {t('页面呈现更新','Presentation updated')}: 2026-09-26</p></section><article class="prose legal-prose wrap">{''.join(f'<section><h2>{h}</h2><p>{p}</p></section>' for h,p in sections)}<section><h2>{t('7. 联系','7. Contact')}</h2><p>{t('有关本政策、Beta 或申请信息删除的问题，请联系','For policy, beta or application-deletion questions, contact')} <a href="mailto:{EMAIL}">{EMAIL}</a>{t("。", ".")}</p></section>{f'<aside class="notice"><p>{t("网站示例补充说明：示例输入只在当前页面内存中使用，不上传或持久保存；刷新即清除。网站托管和 FormSubmit 仍有各自的数据处理边界。", "Website sample clarification: inputs are used only in current-page memory, not uploaded or persisted, and clear on reload. Website hosting and FormSubmit have their own data-processing boundaries.")}</p>{a("principles.html",t("查看具体的数据与授权边界","Read the practical data boundaries"))}</aside>' if page=='privacy-policy.html' else ''}</article>'''
        shell(page,'PAIA — '+title,t('PAIA Private Beta 的隐私和使用边界。','Privacy and usage boundaries for the PAIA private beta.'),content)
    thanks=f'''<section class="page-intro compact-intro wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h1>{t('接下来，留意你的邮箱。','Next, keep an eye on your inbox.')}</h1><p class="lead">{t('申请不等于获得测试资格。若收到邀请，你会获得安装说明、当前限制与反馈方式。','An application is not an invitation. Invited participants receive setup instructions, current limitations and a feedback path.')}</p><p>{t('此页面本身不确认表单是否送达。没有看到 FormSubmit 的成功结果，或提交时遇到错误？请返回重试，或直接写信联系。','This page alone does not confirm delivery. If you did not see a successful FormSubmit response, or encountered a submission error, return to the form or email us directly.')}</p><div class="actions">{button('index.html',t('回到 PAIA','Back to PAIA'))}{a('beta.html',t('返回申请表','Return to the form'),'text-link')}</div><p class="small"><a href="mailto:{EMAIL}">{EMAIL}</a></p></section>'''
    shell('thanks.html',t('PAIA — 申请后的下一步','PAIA — After applying'),t('Private Beta 申请后的下一步与联系渠道。','Next steps and contact after applying to the private beta.'),thanks,True)
    notfound=f'''<section class="page-intro compact-intro wrap"><p class="eyebrow">404</p><h1>{t('这页没有找到。','This page wasn’t found.')}</h1><p class="lead">{t('链接可能已变化。你的扩展档案不在这个网站里，不受影响。','The link may have changed. Your extension archive is not stored on this website and is unaffected.')}</p><div class="actions">{button('index.html',t('回到首页','Back to home'))}{a('demo.html',t('体验示例','Try the sample'),'text-link')}</div></section>'''
    shell('404.html',t('PAIA — 页面未找到','PAIA — Page not found'),t('返回 PAIA 首页。','Return to the PAIA homepage.'),notfound,True)

for lang in ['zh','en']: build(lang)
# Absolute root paths target the existing custom-domain root deployment.
urls=[]
for locale in ['', 'zh/']:
    for name in ['', 'beta.html','principles.html','status.html','about.html','privacy-policy.html','terms.html']:
        urls.append(f'<url><loc>{BASE}/{locale}{name}</loc></url>')
write(ROOT/'sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(urls)+'</urlset>\n')
write(ROOT/'robots.txt','User-agent: *\nAllow: /\nSitemap: https://inputarchive.com/sitemap.xml\n')
if CHECK:
    changed=[name for name,body in GENERATED.items() if not (ROOT/name).exists() or (ROOT/name).read_text(encoding='utf-8')!=body]
    if changed: raise SystemExit('Generated website drift: '+', '.join(changed))
else:
    (ROOT/'website/generated-paths.txt').write_text('\n'.join(sorted(GENERATED))+'\n',encoding='utf-8')
print(('Checked' if CHECK else 'Generated'),len(GENERATED),'website files')
